#include <stdio.h>

int main()
{
    printf("[Escape Sequence]\n");
    printf("\\n : 줄바꿈\n");
    printf("\\t : 탭\n\n");
    printf("안녕하세요\t반갑습니다.\n");
    return 0;
}
